// 负责对下载完成并已入库的简历文件进行·子[lock-candidate] — 由 Agent 工厂从本体动作 `processResume__lock-candidate-ownership`(Agents-generation)生成。
// trigger: agents-gener-process-resume-sub-lock-candidate-ownership.invoked → emit: (terminal)
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface agents-gener-process-resume-sub-lock-candidate-ownershipInput {
  candidate_name: string; // 候选人姓名
  candidate_phone: string; // 候选人手机号
  recruiter_id: string; // 当前操作的 Recruiter ID
  job_requisition_id: string; // 岗位编号
}

interface agents-gener-process-resume-sub-lock-candidate-ownershipOutput {
  lock_status: string; // ok 或 conflict
  candidate_id: string; // 匹配到的候选人 ID，新候选人时为新生成的 ID
  conflict_recruiter_id: string; // 冲突时已锁定该候选人的 Recruiter ID
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是候选人归属锁定专家。你的职责是：基于已解析的候选人姓名和手机号，检查系统中是否已存在该候选人记录，并判断是否存在归属锁定冲突。
判断逻辑：
1. 若系统中不存在该候选人（姓名+手机号均未匹配），则为新候选人，允许锁定，返回 lock_status=ok。
2. 若系统中存在该候选人且归属于当前 recruiter，则更新锁定时间，返回 lock_status=ok。
3. 若系统中存在该候选人但归属于其他 recruiter，则返回 lock_status=conflict，携带冲突的 recruiter_id。
确保每个候选人有且只能归属一名 Recruiter，防止多人同时跟进同一候选人。`;

export const agents-gener-process-resume-sub-lock-candidate-ownershipAgent = defineAgent({
  id: "agents-gener-process-resume-sub-lock-candidate-ownership",
  name: "agents-gener-process-resume-sub-lock-candidate-ownership",
  actor: ["Agent"],
  trigger: ["agents-gener-process-resume-sub-lock-candidate-ownership.invoked"],
  emit: [],
  tools: [],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // (此 agent 不依赖外部工具)
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      await ctx.emit("DONE", { ...input, ...decision });
      return { ok: true };
  },
});
